<?php
require __DIR__.'/bootstrap.php';require_perm('invoices.view');$me=user();$branch=is_admin()?null:require_branch();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();require_perm('invoices.create');$receiver=trim($_POST['receiver']);$description=trim($_POST['description']);$qty=(float)$_POST['qty'];$rate=(float)$_POST['rate'];if(!$receiver||!$description||$qty<=0||$rate<=0){flash('danger','Customer, description, quantity, and rate are required.');redirect('quotations.php');}$amount=round($qty*$rate,2);$no='QTN-'.date('Y').'-'.str_pad((string)(1+(int)$pdo->query("SELECT COUNT(*) FROM general_invoices WHERE document_type='Quotation'")->fetchColumn()),5,'0',STR_PAD_LEFT);$ib=$branch??(int)$_POST['branch_id'];$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO general_invoices(invoice_no,document_type,receiver,phone,description,kg,rate,amount,issue_date,due_date,status,notes,branch_id,created_by) VALUES(?,'Quotation',?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$no,$receiver,trim($_POST['phone']),$description,$qty,$rate,$amount,$_POST['issue_date'],$_POST['due_date'],'Issued',trim($_POST['notes']),$ib,$me['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO general_invoice_items(general_invoice_id,description,kg,rate,amount) VALUES(?,?,?,?,?)')->execute([$id,$description,$qty,$rate,$amount]);$pdo->commit();flash('success',"Quotation $no created.");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Quotation could not be created.');}redirect('quotations.php');}
$rows=$pdo->query("SELECT g.*,b.name branch_name FROM general_invoices g JOIN branches b ON b.id=g.branch_id WHERE g.document_type='Quotation'".($branch===null?'':' AND g.branch_id='.(int)$branch).' ORDER BY g.issue_date DESC,g.id DESC')->fetchAll();$branches=is_admin()?$pdo->query('SELECT id,name,code FROM branches WHERE active=1 ORDER BY name')->fetchAll():[];$title='Quotations';require __DIR__.'/partials/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4"><div><h1 class="h3 fw-bold mb-1">Quotations</h1><p class="text-secondary mb-0">Prepare prices for customers before issuing an invoice.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#quotation"><i class="bi bi-plus-lg"></i> New quotation</button></div>
<div class="card p-3 p-lg-4"><input class="form-control mb-3" style="max-width:420px" data-table-search placeholder="Search quotation or customer"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Quotation</th><th>Customer</th><th>Issued / valid until</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-bold text-primary"><?=e($r['invoice_no'])?></td><td><?=e($r['receiver'])?><small class="d-block text-secondary"><?=e($r['phone']?:'—')?></small></td><td><?=app_date($r['issue_date'])?><small class="d-block text-secondary">Until <?=app_date($r['due_date'])?></small></td><td class="fw-bold"><?=money($r['amount'])?></td><td><span class="status"><?=e($r['status'])?></span></td></tr><?php endforeach?></tbody></table></div></div>
<div class="modal fade" id="quotation"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h2 class="h5 mb-0">New quotation</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="form-label">Customer</label><input class="form-control mb-3" name="receiver" required><label class="form-label">Phone</label><input class="form-control mb-3" name="phone"><?php if(is_admin()):?><label class="form-label">Branch</label><select class="form-select mb-3" name="branch_id"><?php foreach($branches as $b):?><option value="<?=$b['id']?>"><?=e($b['name'].' ('.$b['code'].')')?></option><?php endforeach?></select><?php endif?><label class="form-label">Service description</label><input class="form-control mb-3" name="description" required><div class="row"><div class="col"><label class="form-label">Quantity</label><input class="form-control" type="number" min=".01" step=".01" name="qty" required></div><div class="col"><label class="form-label">Rate</label><input class="form-control" type="number" min=".01" step=".01" name="rate" required></div></div><div class="row mt-3"><div class="col"><label class="form-label">Issue date</label><input class="form-control" type="date" name="issue_date" value="<?=date('Y-m-d')?>" required></div><div class="col"><label class="form-label">Valid until</label><input class="form-control" type="date" name="due_date" value="<?=date('Y-m-d',strtotime('+14 days'))?>" required></div></div><label class="form-label mt-3">Notes</label><textarea class="form-control" name="notes"></textarea></div><div class="modal-footer"><button class="btn btn-primary">Create quotation</button></div></form></div></div><?php require __DIR__.'/partials/footer.php';?>
